function issueSentiment(x){const p=Number(x.issue_positive_count||0),n=Number(x.issue_neutral_count||0),g=Number(x.issue_negative_count||0),total=p+n+g;if(!total)return'Belum dinilai';const max=Math.max(p,n,g);return g===max&&g>n&&g>p?'Negative':p===max&&p>n&&p>g?'Positive':'Neutral'}
function issueContext(x){const pk=x.primary_keyword?.keyword||null,sk=Array.isArray(x.supporting_keywords)?x.supporting_keywords:[],so=Array.isArray(x.supporting_opds)?x.supporting_opds:[],ds=Array.isArray(x.districts)?x.districts:[];const region=x.geographic_scope==='CITYWIDE'?'Seluruh Kota Batam':x.geographic_scope==='DISTRICTS'?(ds.map(d=>d.name).filter(Boolean).join(' · ')||'Belum ditetapkan'):'Belum ditetapkan';return `<div class="mt-3 text-[11px] leading-6"><div><span class="text-slate-500">Keyword Utama:</span> <b class="text-cyan-300">${esc(pk||'Tidak ada')}</b></div><div><span class="text-slate-500">Keyword Pendukung:</span> ${sk.length?sk.map(v=>`<span class="text-slate-300">${esc(v.keyword)}</span>`).join(' · '):'<span class="text-slate-400">Tidak ada</span>'}</div><div><span class="text-slate-500">OPD Utama:</span> <b class="text-emerald-300">${esc(x.lead_opd_name||'Tidak ada')}</b></div><div><span class="text-slate-500">OPD Pendukung:</span> ${so.length?so.map(v=>`<span class="text-slate-300">${esc(v.name)}</span>`).join(' · '):'<span class="text-slate-400">Tidak ada</span>'}</div><div><span class="text-slate-500">Wilayah/Kecamatan:</span> <b class="${region==='Belum ditetapkan'?'text-amber-300':'text-sky-300'}">${esc(region)}</b></div></div>`}
function publicationEvidenceEditor(issueId){const list=publicationEvidenceByIssue[String(issueId)]||[],saved=!!publicationEvidenceSavedByIssue[String(issueId)];const cards=list.map(e=>`<div class="rounded-lg border border-slate-800 bg-slate-950/50 p-2 flex items-start justify-between gap-2"><div class="min-w-0"><div class="text-[10px] font-black text-cyan-300">${esc(e.evidence_type)}${e.is_primary?' · BUKTI UTAMA':''}</div><div class="text-[10px] text-slate-300 break-all">${esc(e.url||((e.files||[]).map(f=>f.file_name).join(' · '))||e.file_name||'-')}</div>${e.caption?`<div class="text-[9px] text-slate-500 mt-1">${esc(e.caption)}</div>`:''}</div>${saved?'':`<button data-del-pub-evidence="${e.id}" class="text-rose-300 text-[10px] font-bold">Hapus</button>`}</div>`).join('');return `<div class="mt-3 rounded-xl border border-slate-700 bg-slate-900/50 p-3"><div class="flex justify-between items-center"><div><div class="text-[10px] font-black tracking-wider text-slate-300">BUKTI PUBLIKASI</div><div class="text-[9px] text-slate-500">Maksimal 5 bukti · Website, PDF, atau Gambar</div></div><b class="text-xs">${list.length}/5</b></div><div class="mt-2 space-y-2">${cards||'<div class="text-[10px] text-slate-500">Belum ada bukti publikasi.</div>'}</div>${!saved&&list.length<5?`<div class="mt-3 grid gap-2"><select data-pub-type class="bg-slate-950 border border-slate-700 rounded-lg p-2 text-xs"><option value="WEBSITE">Website</option><option value="PDF">PDF</option><option value="IMAGE">Gambar / Screenshot</option></select><div data-pub-website><input data-pub-url class="w-full bg-slate-950 border border-slate-700 rounded-lg p-2 text-xs" placeholder="URL publikasi website"></div><div data-pub-file class="hidden"><input data-pub-file-input type="file" accept=".pdf" multiple class="w-full text-xs text-slate-300"><select data-pub-channel class="mt-2 w-full bg-slate-950 border border-slate-700 rounded-lg p-2 text-xs"><option value="press_release">Siaran Pers / PDF</option><option value="instagram">Instagram</option><option value="facebook">Facebook</option><option value="tiktok">TikTok</option><option value="threads">Threads</option><option value="x">X</option><option value="youtube">YouTube</option><option value="media_statement">Pernyataan Media</option><option value="other">Lainnya</option></select></div><textarea data-pub-caption class="w-full bg-slate-950 border border-slate-700 rounded-lg p-2 text-xs" rows="2" placeholder="Caption/keterangan (opsional)"></textarea><label class="text-[10px] text-slate-400"><input data-pub-primary type="checkbox" ${list.length?'':'checked'}> Jadikan Bukti Utama</label><button data-add-pub-evidence class="px-3 py-2 rounded-lg bg-cyan-600 text-white text-[10px] font-black" >TAMBAH</button></div>`:''}${!saved&&list.length?`<button data-save-pub-evidence class="mt-3 w-full px-3 py-2 rounded-lg bg-emerald-600 text-white text-[10px] font-black">SIMPAN BUKTI PUBLIKASI</button>`:''}${saved?'<div class="mt-3 text-[10px] font-bold text-emerald-300">✓ Bukti publikasi sudah disimpan dan dikunci.</div><div class="mt-1 text-[9px] text-slate-500">Tandai sudah dipublikasikan untuk membuka Analisa Publikasi.</div>':''}</div>`;}
function historyGapView(gap){const d=gap?.data||gap||{},a=d.semanticAssessment||{},angles=a.coverage||[],groups={};angles.forEach(v=>{const k=v.group||v.key||'OTHER';(groups[k]||(groups[k]={label:v.groupLabel||v.label||String(k).replaceAll('_',' '),items:[]})).items.push(v)});const status=a.status||d.baselineStatus||'UNASSESSED';return `<div class="space-y-3"><div class="flex flex-wrap gap-2 items-center"><span class="px-2 py-1 rounded-md border border-cyan-500/20 bg-cyan-500/10 text-cyan-300 text-[10px] font-black">${esc(String(status).replaceAll('_',' '))}</span><span class="text-[10px] text-slate-500">${angles.length} claim dianalisis</span></div>${Object.values(groups).map(g=>`<div class="rounded-lg bg-slate-950/50 border border-slate-800 p-3"><div class="text-xs font-black">${esc(g.label)}</div><div class="space-y-2 mt-2">${g.items.map((v,i)=>`<div class="rounded-md border border-slate-800 p-2"><div class="flex justify-between gap-2"><div class="text-[11px] leading-relaxed"><span class="text-slate-500 mr-1">${i+1}.</span>${esc(v.claim||v.label||'-')}</div><span class="shrink-0 text-[9px] font-black text-amber-300">${esc(String(v.status||'UNASSESSED').replaceAll('_',' '))} ${Number(v.matchScore||0)}%</span></div>${v.matchedOfficial?.title?`<div class="text-[9px] text-slate-500 mt-1">Respons: ${esc(v.matchedOfficial.title)}</div>`:''}${v.reason?`<div class="text-[10px] text-slate-400 mt-1"><b>Alasan:</b> ${esc(v.reason)}</div>`:''}</div>`).join('')}</div></div>`).join('')||'<div class="text-xs text-slate-500">Tidak ada rincian claim pada snapshot ini.</div>'}${d.geographicAnalysis?.implication||d.externalAngles?.geographicAnalysis?.implication?`<div class="rounded-lg border border-slate-800 p-3 text-xs"><b>Analisis kewilayahan</b><div class="mt-1 text-slate-400">${esc(d.geographicAnalysis?.implication||d.externalAngles?.geographicAnalysis?.implication)}</div></div>`:''}</div>`}
